BEGIN;
DO $$ BEGIN
 IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='rva_app') THEN CREATE ROLE rva_app NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOBYPASSRLS; END IF;
END $$;
GRANT USAGE ON SCHEMA rva TO rva_app;
GRANT SELECT,INSERT,UPDATE ON rva.principals TO rva_app;
GRANT SELECT,INSERT ON rva.audit_events,rva.evidence_objects TO rva_app;
REVOKE TRUNCATE,REFERENCES,TRIGGER ON ALL TABLES IN SCHEMA rva FROM rva_app;
COMMIT;
